}

export const inputClass = "h-11 w-full rounded-xl border border-input bg-[var(--amber-field)] px-3 text-base text-foreground placeholder:text-muted-foreground focus:outline-2 focus:outline-ring"

/** Choices as a row of pills, one selected (a category, a topic). */
export function Pills<T extends string>({ options, value, onChange, label }: { options: readonly T[]; value: T; onChange: (v: T) => void; label: string }) {
  return (
    <div role="radiogroup" aria-label={label} className="flex flex-wrap gap-2">
      {options.map((o) => (
        <button key={o} type="button" role="radio" aria-checked={value === o} onClick={() => onChange(o)}
          className={cn("h-11 rounded-full px-4 text-[0.9375rem] font-medium", value === o ? "bg-primary text-primary-foreground" : "bg-muted text-foreground")}>
          {o}
        </button>
      ))}
    </div>
  )
}

// Undo for deletes, in the app's own UI: removing something shows "Removed X" with Undo in a bar at
// the top of the screen for a few seconds. No browser dialogs, no toasts. The same bar carries the
// one notice that mustn't pass unseen: what the person had typed on the first screen when their AI
// set the app up under them (keep: it stays until it's used or dismissed).
type Undoable = { text: string; undo: () => unknown; label: string; keep: boolean }
let pending: Undoable | null = null
const listeners = new Set<(u: Undoable | null) => void>()
export function offerUndo(text: string, undo: () => unknown, label = "Undo", keep = false) {
  pending = { text, undo, label, keep }
  listeners.forEach((f) => f(pending))
}
export function UndoBar() {
  const [u, setU] = useState<Undoable | null>(null)
  // What was offered before this bar was on screen shows too (the first screen has no bar).
  useLayoutEffect(() => { listeners.add(setU); setU(pending); return () => { listeners.delete(setU) } }, [])
  useEffect(() => {
    if (!u || u.keep) return
    const t = setTimeout(() => { if (pending === u) pending = null; setU((now) => (now === u ? null : now)) }, 6000)
    return () => clearTimeout(t)
  }, [u])
  if (!u) return null
  const close = () => { if (pending === u) pending = null; setU(null) }
  return (
    <div role="status" className="mb-4 animate-in fade-in duration-200 motion-reduce:animate-none">
      <div className="flex w-full items-center gap-1 rounded-xl bg-[var(--amber-accent-soft)] py-1.5 pl-4 pr-1.5 text-foreground">
        <span className={cn("min-w-0 flex-1 text-[0.9375rem]", !u.keep && "truncate")}>{u.text}</span>
        <button type="button" onClick={async () => { close(); await u.undo() }} className="h-10 shrink-0 rounded-lg px-3 font-semibold text-link">{u.label}</button>
        {u.keep && <button type="button" aria-label="Dismiss" onClick={close} className="grid size-10 shrink-0 place-items-center rounded-lg text-muted-foreground"><X className="size-4" /></button>}
      </div>
    </div>
  )
}

/** A new app's first screen, alone in the note: the same frame in all four template apps. A
 *  576 px column in the middle, the title at 2rem with the same space over it, one line saying
 *  what to do, and a quiet line saying the person's AI can do it too (they are asked the same
 *  thing in two places when the app is made with an AI). Then the form, one primary button and
 *  a foot line. */
export function FirstScreen({ title, lead, ai, foot, children }: { title: string; lead: string; ai: string; foot?: string; children: ReactNode }) {
  return (
    <div className="mx-auto w-full max-w-xl" data-testid="first-screen">
      <header className="pb-5 pt-2">
        <h1 className="text-[2rem] font-bold leading-tight tracking-tight">{title}</h1>
        <p className="mt-2 text-muted-foreground text-balance">{lead}</p>
        <p className="mt-1 text-[0.875rem] text-muted-foreground" data-testid="ai-hint">{ai}</p>
      </header>
      {children}
      {foot && <p className="px-1 pb-6 pt-3 text-center text-[0.8125rem] text-muted-foreground text-balance">{foot}</p>}
    </div>
  )
}
/** The padding a first screen has around it when it stands alone (no tabs, no sidebar). */
export const firstScreenPage = "min-h-screen px-4 pt-4 min-[700px]:px-6 min-[900px]:pt-8"

/** A destructive button for the bottom of an edit sheet. */
export function DeleteButton({ children, className, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button type="button" {...props} className={cn("mt-3 inline-flex h-12 w-full items-center justify-center rounded-xl font-semibold text-destructive active:opacity-70", className)}>
      {children}
    </button>
  )
}

/** The big title at the top of a screen, with a line under it and an action on the right. */
export function Title({ title, subtitle, action, className }: { title: string; subtitle?: string; action?: ReactNode; className?: string }) {
  return (
    <header className={cn("flex items-end gap-3 pb-5 pt-2", className)}>
      <div className="min-w-0 flex-1">
        {subtitle && <p className="text-[0.8125rem] font-semibold uppercase tracking-wide text-muted-foreground">{subtitle}</p>}
        <h1 className="text-[2rem] font-bold leading-tight tracking-tight">{title}</h1>
      </div>
      {action}
    </header>
  )
}

/** A section's Edit / Done switch: rows show their reorder and remove buttons while it's on. */
export function EditToggle({ on, onChange, label }: { on: boolean; onChange: (on: boolean) => void; label: string }) {
  return (
    <button type="button" aria-pressed={on} aria-label={on ? `Done editing ${label}` : `Edit ${label}`} onClick={() => onChange(!on)}
      className="inline-flex h-8 items-center rounded-lg px-1 font-semibold text-link">
      {on ? "Done" : "Edit"}
    </button>
  )
}

/** Up, down and remove for one row of a list in edit mode. */
export function RowTools({ name, first, last, onMove, onRemove }: { name: string; first: boolean; last: boolean; onMove: (by: -1 | 1) => unknown; onRemove: () => unknown }) {
  const tool = "grid size-11 shrink-0 place-items-center rounded-full disabled:opacity-25"
  return (
    <>
      <button type="button" aria-label={`Move ${name} up`} disabled={first} onClick={() => onMove(-1)} className={cn(tool, "text-muted-foreground")}><ChevronUp className="size-5" /></button>
      <button type="button" aria-label={`Move ${name} down`} disabled={last} onClick={() => onMove(1)} className={cn(tool, "text-muted-foreground")}><ChevronDown className="size-5" /></button>
      <button type="button" aria-label={`Remove ${name}`} onClick={() => onRemove()} className={cn(tool, "text-destructive")}><Trash2 className="size-5" /></button>
    </>
  )
}

/** Spent of a budget as a line: "299 of 300 kr", the currency once ("$299 of $300" where it goes first). */
export function SpendText({ spent, budget, fmt, className }: { spent: number; budget: number; fmt: (n: number) => string; className?: string }) {
  const a = fmt(spent), b = fmt(budget)
  const unit = b.replace(/^[\d.,\s-]+/, "")
  const short = unit && a.endsWith(" " + unit) ? a.slice(0, -unit.length - 1) : a
  return (
    <p className={cn("text-[0.875rem] tabular-nums text-muted-foreground", className)} data-testid="spend">
      <span className={cn("font-semibold", spent > budget ? "text-destructive" : "text-foreground")}>{short}</span> of {b}
    </p>
  )
}

/** Spent against a budget: "450 of 600 kr" over a bar, the danger colour once it's over. */
export function Spend({ spent, budget, fmt, label, className }: { spent: number; budget?: number; fmt: (n: number) => string; label: string; className?: string }) {
  if (!budget) return spent ? <p className={cn("text-[0.875rem] tabular-nums text-muted-foreground", className)} data-testid="spend">{fmt(spent)} spent</p> : null
  return (
    <div className={className}>
      <SpendText spent={spent} budget={budget} fmt={fmt} />
      <Bar value={spent / budget} over={spent > budget} label={label} className="mt-1 h-1.5" />
    </div>
  )
}

